// Returns 1 when the sample should be white, 0 when it should be ink (black),
// matching Atkinson1BitDitherer::processPixel's convention so it is a drop-in.
inline uint8_t blueNoise1Bit(int gray, int x, int y) {
  if (gray < 0)
    gray = 0;
  else if (gray > 255)
    gray = 255;
  return gray > kBlueNoise64[y & 63][x & 63] ? 1 : 0;
}
